			case 9: return new[] { "나", "우리 관계", "상대", "넘을 과제", "마룡이의 조언" }; case 10: return new[] { "과거", "현재", "숨은 영향", "장애물", "주변 환경", "조언", "가능한 결과" }; case 11: return new[] { "생각", "마음", "행동" };
			default: return new[] { "오늘의 메시지" };
		}
	}
	private static readonly int[] MajYes = { 1, 1, 0, 1, 1, 0, 1, 2, 1, 0, 1, 0, 0, -1, 1, -1, -2, 2, -1, 2, 1, 2 };
	private static readonly int[] RankYes = { 2, 0, 1, 0, -1, 1, 0, 1, 1, 1, 1, 1, 1, 1 };
	private static int YesScore(int id, bool rev)
	{
		int y; if (id < 22) y = MajYes[id]; else
		{
			int m = id - 22, s = m / 14, r = m % 14; y = RankYes[r];
			if (s == 2) { if (r == 0) y = 1; else if (r == 2 || r == 4 || r == 8 || r == 9) y = -2; else if (r == 7) y = -1; else if (r < 10) y = 0; }
			if (s == 0 && r == 9) y = -1; if (s == 3 && r == 8) y = 2; if (s == 1 && r == 4) y = -1; if (s == 1 && (r == 8 || r == 9)) y = 2; if (s == 1 && r == 6) y = -1;
		}
		return rev ? -y : y;
	}
	private static string Verdict(int y) { return y >= 2 ? "예! 확실히 긍정이에요" : (y == 1 ? "아마도 예예요" : (y == 0 ? "보류 · 조건부예요" : (y == -1 ? "아마도 아니오예요" : "아니오, 지금은 아니에요"))); }
	private static string VerdictText(int y) { return y >= 2 ? "흐름이 강하게 받쳐 줘요. 자신 있게 진행하세요." : (y == 1 ? "조건이 맞으면 잘 풀려요. 세부만 점검하세요." : (y == 0 ? "아직 답이 정해지지 않았어요. 정보를 더 모으고 시기를 보세요." : (y == -1 ? "걸림돌이 있어요. 계획을 보완하면 달라질 수 있어요." : "지금은 흐름이 막혀 있어요. 시기를 늦추거나 방향을 바꿔 보세요."))); }

