	private string Synth()
	{
		int N = slots.Length; if (N < 2 || mode == 4 || mode == 5 || mode == 7 || mode == 8) return null;
		int[] sc = new int[N]; int best = 0, worst = 0; for (int i = 0; i < N; i++) { sc[i] = YesScore(slots[i].Card, slots[i].Rev); if (sc[i] > sc[best]) best = i; if (sc[i] < sc[worst]) worst = i; }
		List<string> L = new List<string>(); int h = Math.Max(1, N / 2); double a0 = 0, a1 = 0; for (int i = 0; i < h; i++) a0 += sc[i]; for (int i = N - h; i < N; i++) a1 += sc[i]; a0 /= h; a1 /= h;
		string fn = CardName(slots[0].Card), ln = CardName(slots[N - 1].Card);
		L.Add("● 흐름: 처음 '" + fn + "' → 마지막 '" + ln + "'. " + (a1 - a0 >= 1 ? "뒤로 갈수록 기운이 올라가요. 지금의 답답함은 지나가는 구간이에요." : (a0 - a1 >= 1 ? "뒤로 갈수록 힘이 빠져요. 초반의 좋은 기운이 있을 때 중요한 일을 먼저 끝내 두세요." : "큰 오르내림 없이 비슷한 흐름이에요. 꾸준함이 열쇠예요.")));
		if (sc[best] > sc[worst]) L.Add("● " + TopicLine[topic].Replace("{B}", CardName(slots[best].Card)).Replace("{bk}", CardKw(slots[best].Card)).Replace("{W}", CardName(slots[worst].Card)).Replace("{wk}", CardKw(slots[worst].Card)) + " (" + posN[best] + " ↔ " + posN[worst] + ")");
		int shown = 0; for (int p = 0; p < PairMaj.Length && shown < 3; p++) { int ia = -1, ib = -1; for (int i = 0; i < N; i++) { if (slots[i].Card == PairMaj[p][0]) ia = i; if (slots[i].Card == PairMaj[p][1]) ib = i; } if (ia >= 0 && ib >= 0) { L.Add("● " + PairTx[p]); shown++; } }
		int[] su = new int[4]; foreach (Slot s in slots) if (s.Card >= 22) su[(s.Card - 22) / 14]++;
		string[] pr = new string[6]; int[][] pc = { new[] { 0, 3 }, new[] { 0, 1 }, new[] { 0, 2 }, new[] { 1, 3 }, new[] { 1, 2 }, new[] { 2, 3 } }; int bp = -1, bv = 0;
		for (int k = 0; k < 6; k++) { int v = Math.Min(su[pc[k][0]], su[pc[k][1]]); if (v > bv) { bv = v; bp = k; } }
		if (bp >= 0) L.Add("● " + ElPair[bp]); else { int bs = 0; for (int i = 1; i < 4; i++) if (su[i] > su[bs]) bs = i; if (su[bs] >= 3) L.Add("● " + SuitDom[bs].Replace(" 쪽", "") + " 기운이 한쪽으로 크게 쏠려 있어요. 다른 영역(관계·일·돈·생각)도 한 번씩 돌아보세요."); }
		for (int r = 0; r < 10; r++) { int cnt = 0; foreach (Slot s in slots) if (s.Card >= 22 && (s.Card - 22) % 14 == r) cnt++; if (cnt >= 2) { L.Add("● 같은 숫자(" + RankName[r] + ")가 겹쳤어요 → 이번 질문의 핵심 주제: " + RankTheme[r] + "."); break; } }
		for (int i = 0; i < N; i++) if (slots[i].Card >= 22 && (slots[i].Card - 22) % 14 >= 10) { L.Add("● 궁정 카드 '" + CardName(slots[i].Card) + "'(" + posN[i] + ") → " + CourtTx[(slots[i].Card - 22) % 14 - 10] + "예요."); break; }
		List<string> rv = new List<string>(); for (int i = 0; i < N; i++) if (slots[i].Rev) rv.Add(CardName(slots[i].Card)); if (rv.Count > 0) L.Add("● 역방향(" + string.Join(", ", rv.ToArray()) + "): 그 에너지가 막혀 있거나 안으로 향해 있어요. 밖의 탓보다 내 안의 준비와 속도를 먼저 점검하세요.");
		int mj = 0; double ar = 0; int nm = 0; foreach (Slot s in slots) { if (s.Card < 22) mj++; else { ar += (s.Card - 22) % 14; nm++; } }
		L.Add("● 메이저 " + mj + "장: " + (mj * 2 >= N ? "개인의 노력보다 큰 시기와 운명의 흐름이 이번 질문을 좌우해요. 흐름을 거스르지 말고 올라타세요." : (mj == 0 ? "모두 일상의 카드예요. 내 선택과 노력으로 바꿀 수 있는 영역이라 행동이 곧 답이에요." : "큰 흐름과 일상의 노력이 함께 작용해요. 흐름은 받아들이고 디테일은 내가 정해요.")));
		if (nm > 0) L.Add("● 시기: " + (ar / nm < 4 ? "숫자가 작은 카드가 많아 이제 막 시작된 일이에요. 며칠~몇 주 안에 신호가 보여요." : (ar / nm < 8 ? "중간 단계의 카드가 많아 몇 주~몇 달에 걸쳐 진행돼요." : "숫자가 큰 카드가 많아 끝이 가까운 일이에요. 마무리 후 다음 국면이 와요.")));
		for (int k = 0; k < 4 && N >= 3; k++) if (su[k] == 0 && su[0] + su[1] + su[2] + su[3] >= 2) { L.Add("● 빈 기운: " + SuitDom[k].Replace(" 쪽", "") + " 쪽 카드가 없어요. 사주의 빈 오행처럼 이 영역은 의식해서 채워야 균형이 맞아요 → " + SuitLucky[k] + "."); break; }
		if (N >= 3) L.Add("● 한 줄 줄거리: 뿌리 '" + CardKw(slots[0].Card) + "' → 현재 '" + CardKw(slots[N / 2].Card) + "' → 앞으로 '" + CardKw(slots[N - 1].Card) + "' 순서로 이어져요.");
		List<string> S = new List<string>();
		if ((mode == 2 || mode == 9) && N >= 3)
		{
			int ia = 0, ib = mode == 2 ? 1 : 2; bool pa = sc[ia] > 0, pb = sc[ib] > 0;
			S.Add("● 두 사람의 온도: " + (pa && pb ? "서로 비슷한 온도로 마음이 향해요. 표현만 하면 빠르게 가까워져요." : (pa ? "내 마음은 열려 있는데 상대는 아직 닫혀 있어요. 재촉하지 말고 거리를 두며 신호를 기다리세요." : (pb ? "상대는 호의가 있는데 내가 망설이고 있어요. 내 마음부터 정리해 보세요." : "서로 지쳐 있거나 마음이 멀어져 있어요. 관계를 어떻게 이어 갈지 솔직하게 다시 정해야 해요."))));
		}
		int stp = N <= 5 ? 1 : 2, cntp = 0;
		for (int i = 0; i + 1 < N && cntp < 5; i += stp, cntp++)
		{
			int ca = sc[i] >= 1 ? 0 : (sc[i] <= -1 ? 2 : 1), cb = sc[i + 1] >= 1 ? 0 : (sc[i + 1] <= -1 ? 2 : 1); string el = "";
			if (slots[i].Card >= 22 && slots[i + 1].Card >= 22) { int xa = (slots[i].Card - 22) / 14, xb = (slots[i + 1].Card - 22) / 14; if (xa == xb) el = " 같은 계열이라 이 이야기가 한 가지 주제로 깊어져요."; else for (int k = 0; k < 6; k++) if ((pc[k][0] == xa && pc[k][1] == xb) || (pc[k][0] == xb && pc[k][1] == xa)) el = " " + ElPair[k]; }
			for (int p = 0; p < PairMaj.Length; p++) if ((PairMaj[p][0] == slots[i].Card && PairMaj[p][1] == slots[i + 1].Card) || (PairMaj[p][1] == slots[i].Card && PairMaj[p][0] == slots[i + 1].Card)) { S.Add("● " + posN[i] + " '" + CardName(slots[i].Card) + "' + " + posN[i + 1] + " '" + CardName(slots[i + 1].Card) + "' → " + PairTx[p].Substring(PairTx[p].IndexOf(". ") + 2)); goto nextPair; }
			S.Add("● " + posN[i] + " '" + CardName(slots[i].Card) + (slots[i].Rev ? "(역)" : "") + "'(" + CardKw(slots[i].Card) + ") 뒤에 " + posN[i + 1] + " '" + CardName(slots[i + 1].Card) + (slots[i + 1].Rev ? "(역)" : "") + "'(" + CardKw(slots[i + 1].Card) + ") 카드가 이어져요 → " + Trans[ca * 3 + cb] + el + (slots[i].Card < 22 && slots[i + 1].Card < 22 ? " 둘 다 메이저라 인생의 큰 주제예요." : (slots[i].Card >= 22 && slots[i + 1].Card >= 22 ? " 둘 다 마이너라 일시적인 상황이니 노력으로 바꿀 수 있어요." : " 메이저는 '왜'를, 마이너는 '어떻게'를 보여 줘요.")));
			nextPair:;
		}
		double av = 0; for (int i = 0; i < N; i++) av += sc[i]; av /= N;
		S.Add("● 종합 결론: " + Verd[topic * 3 + (av >= 0.6 ? 0 : (av <= -0.4 ? 2 : 1))]);
		string ak = Act(slots[best].Card); S.Add("● 핵심 열쇠 카드 '" + CardName(slots[best].Card) + "' → " + ak.Substring(ak.IndexOf('·') + 2));
		int nr = 0, nc = 0; for (int i = 0; i < N; i++) { if (slots[i].Rev) nr++; if (slots[i].Card >= 22 && (slots[i].Card - 22) % 14 >= 10) nc++; }
		if (N >= 3 && nr == 0) S.Add("● 방향: 모두 정방향이라 기운이 밖으로 시원하게 흘러요. 겉으로 드러나는 일이에요."); else if (N >= 3 && nr == N) S.Add("● 방향: 모두 역방향이라 막힌 기운이거나 겉으로 드러나지 않은 내면의 이야기예요. 속마음부터 돌보세요.");
		if (nc >= 2) S.Add("● 궁정 카드 " + nc + "장: 이번 이야기에는 여러 사람이 등장해요. 각자의 성숙도(시종·기사·여왕·왕)에 따라 힘의 균형이 달라져요.");
		S.Add("— 세부 포인트 —"); S.AddRange(L);
		return string.Join("\n", S.ToArray());
	}
	private static readonly string[] Trans = {
		"좋은 기운이 이어져 쌓여요. 이 흐름을 끊지 않게 같은 방향으로 계속 가세요.", "좋은 출발이 안정 단계로 접어들어요. 속도를 유지하며 점검하세요.", "좋던 흐름에 제동이 걸려요. 앞의 장점에 취하지 말고 뒤 카드의 경고를 먼저 챙기세요.",
		"평범하던 흐름이 좋은 쪽으로 열려요. 작은 시도가 큰 결과로 이어져요.", "큰 변화 없이 이어져요. 내 선택과 노력이 방향을 정해요.", "무난하던 곳에 걸림돌이 나타나요. 미리 대비하면 큰 문제는 아니에요.",
		"어려움이 풀리는 반전 구조예요. 지금의 고비는 뒤 카드의 해답을 위한 과정이에요.", "어려움이 가라앉으며 평온해져요. 서두르지 말고 정리하세요.", "문제가 이어져 겹쳐요. 한 번 멈춰 원인을 짚고 도움을 구하세요." };
	private static readonly string[] Verd = {
		"전체적으로 순풍이에요. 지금 구상한 방향으로 자신 있게 나아가도 좋아요.", "좋고 나쁨이 섞여 있어 내 선택이 결과를 가르는 상황이에요. 장점은 살리고 걸림돌은 미리 막으세요.", "지금은 속도보다 점검이 필요해요. 무리한 결정은 미루고 기반부터 다지면 흐름이 바뀌어요.",
		"마음이 통하고 관계가 따뜻해지는 흐름이에요. 먼저 한 걸음 다가가 보세요.", "기대와 불안이 섞여 있어요. 마음을 말로 확인하면 방향이 분명해져요.", "오해와 거리감이 생기기 쉬워요. 감정이 가라앉은 뒤 차분히 대화하세요.",
		"노력이 인정받는 흐름이에요. 미뤄 둔 도전이나 제안을 지금 꺼내세요.", "성과와 장애가 함께 와요. 우선순위를 정하고 하나씩 끝내세요.", "과부하와 실수에 주의하세요. 일정을 줄이고 검토를 한 번 더 하세요.",
		"기회가 들어오는 흐름이에요. 계획한 만큼만 과감하게 움직이세요.", "들어오는 돈과 나가는 돈이 비슷해요. 고정 지출부터 점검하세요.", "새는 돈과 충동 지출에 주의하세요. 큰 결정은 며칠 미루세요.",
		"컨디션이 회복되는 흐름이에요. 좋은 습관을 이어 가세요.", "피로가 쌓였다 풀렸다 해요. 수면과 식사 리듬을 먼저 맞추세요.", "몸이 보내는 경고에 귀 기울이세요. 무리하지 말고 쉬고, 필요하면 진료를 받으세요." };
}
